        ".....###..###..##..###..###.....",
        ".....###..####....####..###.....",
        ".....###..############..###....."
      ],
      
      body: [
        ".....###..#####..#####..###.....",
        ".....###..####.##.####..###.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
