        "....###...00.######.00...###....",
        "...####....####..####....####...",
        "..#####...####....####...#####..",
        ".#######.####..##..####.#######.",
        ".###########..####..###########.",
        ".###...####..######..####...###.",
        "..####..##..##....##..##..####..",
        "...####....##..##..##....####...",
        "....####..####....####..####....",
        ".....###..############..###.....",
        ".....###..####....####..###.....",
        ".....###..###..##..###..###.....",
        ".....###..##..####..##..###.....",
        ".....###..###..##..###..###.....",
