      else if (v1.x === -1 && v2.y === 1) bodySprite = sprites.turnLeftRight;
      else if (v1.y === 1 && v2.x === 1) bodySprite = sprites.turnLeftDown;
      else if (v1.x === 1 && v2.y === -1) bodySprite = sprites.turnLeftLeft;
      else bodySprite = sprites.turnLeftUp;
    }
  }
  drawSprite(ctx, bodySprite, x, y, grid, colors.green, colors.line);
}

