        "..####..##..##....##..##..####..",
        "...####....##..##..##....####...",
        "....####..####....####..####....",
        ".....###..############..###.....",
        ".....###..####....####..###.....",
        ".....###..###..##..###..###.....",
        ".....###..##..####..##..###.....",
        ".....###..###..##..###..###.....",
        ".....###..####....####..###.....",
        ".....###..############..###....."
      ],
      
      body: [
        ".....###..#####..#####..###.....",
        ".....###..####.##.####..###.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
