      ],
      turnLeft: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        ".....##########..##########.....",
        ".....##########..##########.....",
        ".....##########..##########.....",
        ".....##########..##########.....",
        ".....##########..##########.....",
